import{_ as a,c as t,o as s,ag as n}from"./chunks/framework.CQuhCYrb.js";const h=JSON.parse('{"title":"AI Prompting","description":"","frontmatter":{"title":"AI Prompting"},"headers":[],"relativePath":"ai-ml/ai-prompting.md","filePath":"ai-ml/ai-prompting.md","lastUpdated":null}'),i={name:"ai-ml/ai-prompting.md"};function r(o,e,p,l,c,d){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="ai-prompting" tabindex="-1">AI Prompting <a class="header-anchor" href="#ai-prompting" aria-label="Permalink to &quot;AI Prompting&quot;">​</a></h1><h2 id="ai-ml-prompting-guide-for-research-processing-and-analysis" tabindex="-1">AI/ML Prompting Guide for Research, Processing, and Analysis <a class="header-anchor" href="#ai-ml-prompting-guide-for-research-processing-and-analysis" aria-label="Permalink to &quot;AI/ML Prompting Guide for Research, Processing, and Analysis&quot;">​</a></h2><p>return to [</p><h3 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h3><p>This guide helps users employ AI/ML technologies effectively to enhance research collection, processing, and analysis. It provides structured prompts with placeholders for direct use in conversational AI applications like ChatGPT.</p><h3 id="prompting-strategies" tabindex="-1">Prompting Strategies <a class="header-anchor" href="#prompting-strategies" aria-label="Permalink to &quot;Prompting Strategies&quot;">​</a></h3><h3 id="_1-write-clear-instructions" tabindex="-1">1. Write Clear Instructions <a class="header-anchor" href="#_1-write-clear-instructions" aria-label="Permalink to &quot;1. Write Clear Instructions&quot;">​</a></h3><p>Ensure your instructions are specific and direct to get the most relevant and accurate responses from AI.</p><h4 id="prompt-template" tabindex="-1">Prompt Template: <a class="header-anchor" href="#prompt-template" aria-label="Permalink to &quot;Prompt Template:&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&amp;quot;Analyze [detailed description of the topic or data](ml](/ml)) focusing on [aspects](specific). Summarize the findings in [length or format](desired).&amp;quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_2-provide-reference-text" tabindex="-1">2. Provide Reference Text <a class="header-anchor" href="#_2-provide-reference-text" aria-label="Permalink to &quot;2. Provide Reference Text&quot;">​</a></h3><p>Giving reference texts helps the AI understand the context or background of your query better.</p><h4 id="prompt-template-1" tabindex="-1">Prompt Template: <a class="header-anchor" href="#prompt-template-1" aria-label="Permalink to &quot;Prompt Template:&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&amp;quot;Considering the information provided in [text or document](reference), discuss [question or topic](specific). Include any necessary citations from [sources or databases](specific).&amp;quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_3-split-complex-tasks" tabindex="-1">3. Split Complex Tasks <a class="header-anchor" href="#_3-split-complex-tasks" aria-label="Permalink to &quot;3. Split Complex Tasks&quot;">​</a></h3><p>Complex tasks should be divided into simpler, more manageable sub-tasks.</p><h4 id="prompt-template-2" tabindex="-1">Prompt Template: <a class="header-anchor" href="#prompt-template-2" aria-label="Permalink to &quot;Prompt Template:&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&amp;quot;Step 1: Outline the main arguments found in [or text](document). Step 2: Evaluate the implications of these arguments on [field or issue](specific). Step 3: Predict future trends based on this evaluation.&amp;quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_4-give-the-model-time-to-think" tabindex="-1">4. Give the Model Time to “Think” <a class="header-anchor" href="#_4-give-the-model-time-to-think" aria-label="Permalink to &quot;4. Give the Model Time to “Think”&quot;">​</a></h3><p>Prompt the AI to consider the response more deeply by asking it to explain its reasoning process.</p><h4 id="prompt-template-3" tabindex="-1">Prompt Template: <a class="header-anchor" href="#prompt-template-3" aria-label="Permalink to &quot;Prompt Template:&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&amp;quot;Before answering, consider the factors affecting [or issue](topic). What are the potential impacts of [factor](specific)? Explain your reasoning.&amp;quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_5-use-external-tools" tabindex="-1">5. Use External Tools <a class="header-anchor" href="#_5-use-external-tools" aria-label="Permalink to &quot;5. Use External Tools&quot;">​</a></h3><p>Leverage the AI’s ability to integrate with external tools for enhanced data retrieval or analysis.</p><h4 id="prompt-template-4" tabindex="-1">Prompt Template: <a class="header-anchor" href="#prompt-template-4" aria-label="Permalink to &quot;Prompt Template:&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&amp;quot;Use the data from [database or API](external) to calculate [calculation](specific). Summarize the results and explain how they impact [topic or issue](related).&amp;quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_6-test-changes-systematically" tabindex="-1">6. Test Changes Systematically <a class="header-anchor" href="#_6-test-changes-systematically" aria-label="Permalink to &quot;6. Test Changes Systematically&quot;">​</a></h3><p>Regularly evaluate the effectiveness of your prompts and the accuracy of the AI’s responses.</p><h4 id="prompt-templates" tabindex="-1">Prompt Templates: <a class="header-anchor" href="#prompt-templates" aria-label="Permalink to &quot;Prompt Templates:&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create an advanced query for $SearchEnginePlatform using $Language incorporating the information below:</span></span>
<span class="line"><span>Searching for:</span></span>
<span class="line"><span>Region: CountryX</span></span>
<span class="line"><span>Language: Local Language of $Region</span></span>
<span class="line"><span>SearchEnginePlatform: Google</span></span>
<span class="line"><span>Data Type should include: PDF</span></span>
<span class="line"><span>Media Type: News Database Report WIKI Repository</span></span>
<span class="line"><span>Date Range: a month</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="prompting-strategies-1" tabindex="-1">Prompting Strategies <a class="header-anchor" href="#prompting-strategies-1" aria-label="Permalink to &quot;Prompting Strategies&quot;">​</a></h3>`,31)])])}const u=a(i,[["render",r]]);export{h as __pageData,u as default};
